package com.influencermatch.backend.auth.service;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.*;import java.util.*;
import com.influencermatch.backend.auth.model.*;import com.influencermatch.backend.auth.repository.EmailVerificationDeliveryRepository;import com.influencermatch.backend.exception.*;import org.junit.jupiter.api.Test;
class OtpChallengePolicyTest {
 final EmailOtpCodes crypto=new EmailOtpCodes("purpose-test-secret-at-least-32-characters");final Clock clock=Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC);
 @Test void purposesCannotUseEachOthersHashEvenForSameCodeAndAccount(){var state=new PasswordSetupOtp();state.setUserId(UUID.randomUUID());state.setExpiresAt(clock.instant().plusSeconds(600));state.setCodeHash(crypto.hash(state.getUserId(),"000042"));assertThatThrownBy(()->OtpChallengePolicy.verify(state,OtpChallengePolicy.Purpose.PASSWORD_SETUP,"000042",crypto,clock)).isInstanceOf(EmailOtpAttemptException.class);assertThat(state.getAttempts()).isEqualTo(1);assertThat(state.getConsumedAt()).isNull();state.setCodeHash(crypto.hash(state.getUserId(),"password-setup","000042"));OtpChallengePolicy.verify(state,OtpChallengePolicy.Purpose.PASSWORD_SETUP,"000042",crypto,clock);assertThat(state.getConsumedAt()).isEqualTo(clock.instant());}
 @Test void deliveryBudgetIsSharedAcrossPurposes(){var deliveries=mock(EmailVerificationDeliveryRepository.class);var id=UUID.randomUUID();when(deliveries.countByUserIdAndSentAtAfter(id,clock.instant().minusSeconds(3600))).thenReturn(5L);assertThatThrownBy(()->OtpChallengePolicy.issue(new PasswordSetupOtp(),id,OtpChallengePolicy.Purpose.PASSWORD_SETUP,crypto,clock,deliveries)).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.code()).isEqualTo(ErrorCode.EMAIL_OTP_RATE_LIMITED));verify(deliveries,never()).save(any());}
}
